<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { Background } from '@vue-flow/background'
import { Handle, Position, VueFlow, useVueFlow } from '@vue-flow/core'
import '@vue-flow/core/dist/style.css'
import '@vue-flow/core/dist/theme-default.css'
import { layoutGraph } from '../features/workbench/dagLayout'
import { COLLAB_STAGES, type ApprovalLevel, type CollabStage } from '../api/collab-projects.api'

const props=defineProps<{ stages:CollabStage[]; mode?:'requirement'|'template'; approvalLevel?:ApprovalLevel }>()
const emit=defineEmits<{openStage:[stageKey:string]}>()
const order=COLLAB_STAGES.map(s=>s.key);const links=[['REQUIREMENT','PRODUCT'],['PRODUCT','ARCHITECTURE_DESIGN'],['PRODUCT','UI_DESIGN'],['ARCHITECTURE_DESIGN','BACKEND_CODING'],['UI_DESIGN','FRONTEND_CODING'],['BACKEND_CODING','TESTING'],['FRONTEND_CODING','TESTING'],['TESTING','ACCEPTANCE']]
type Node={id:string;position:{x:number;y:number};data:Record<string,unknown>;class?:string};type Edge={id:string;source:string;target:string;type:string;sourceHandle:string;targetHandle:string;class:string}
const nodes=ref<Node[]>([]);const edges=ref<Edge[]>([]);const byKey=computed(()=>new Map(props.stages.map(s=>[s.stageKey,s])));const {fitView}=useVueFlow()
function tone(status:string){return status==='COMPLETED'?'success':['IN_PROGRESS','PENDING_APPROVAL','REJECTED','READY_BLOCKED'].includes(status)?'warning':status==='SKIPPED'?'muted':'info'}
function subtitle(s:CollabStage|undefined){if(!s)return '未纳入模板';if(s.status==='SKIPPED')return '未纳入流程';const reviewerAssigned=s.reviewerRoleActors?s.reviewerRoleActors.some(role=>role.userIds.length>0):Boolean(s.reviewerUserIds?.length||s.reviewerUserId||s.additionalReviewerUserIds?.length);const auto=props.mode!=='template'&&(props.approvalLevel==='L3'||props.approvalLevel==='L2'&&!reviewerAssigned);const roles=`负责人：${s.ownerRoleName||'未配置'} · ${auto?'无需审批 · 自动流转':`审批：${s.reviewerRoleNames?.join('、')||s.reviewerRoleName||'自动流转'}`}`;return s.status==='READY_BLOCKED'?`待补齐人员 · 补齐后自动启动 · ${roles}`:roles}
async function render(){try{const ns=order.map(id=>({id,width:232,height:92}));const es=links.map((l,i)=>({id:`e${i}`,source:l[0],target:l[1]}));const pos=await layoutGraph(ns,es,{layerGap:64,nodeGap:30,padding:20});nodes.value=order.map((key,i)=>{const s=byKey.value.get(key);return{id:key,position:pos[key]||{x:0,y:0},data:{title:`${String((s?.stageOrder||s?.order||i+1)).padStart(2,'0')} ${s?.title||COLLAB_STAGES[i]?.title||key}`,sub:subtitle(s),tone:tone(s?.status||'SKIPPED')},class:`flow-node flow-${tone(s?.status||'SKIPPED')}`}});edges.value=es.map(e=>({id:e.id,source:e.source,target:e.target,type:'default',sourceHandle:'out',targetHandle:'in',class:'flow-edge'}));await nextTick();await fitView({padding:.12,includeHiddenNodes:true})}catch{nodes.value=[];edges.value=[]}}
function open(e:{node:{id:string}}){emit('openStage',e.node.id)}
watch(()=>props.stages,render,{deep:true});onMounted(render)
</script>

<template><section class="workflow"><header><div><h2>{{mode==='template'?'研发流程模板':'需求研发流程'}}</h2><p>{{mode==='template'?'节点展示阶段关联的角色；点击节点可跳转到下方配置。':'点击阶段查看详情；人员和流程开关在下方阶段清单中调整。'}}</p></div><div class="legend"><template v-if="mode==='template'"><span><i class="blue"/>默认纳入</span><span><i class="gray"/>未纳入</span></template><template v-else><span><i class="green"/>已归档</span><span><i class="yellow"/>进行中</span><span><i class="blue"/>待开始</span><span><i class="gray"/>跳过</span></template></div></header><div class="canvas"><VueFlow :nodes="nodes" :edges="edges" :nodes-draggable="false" :nodes-connectable="false" :elements-selectable="false" :zoom-on-scroll="false" :pan-on-drag="false" fit-view-on-init @node-click="open"><Background :gap="22" pattern-color="rgba(102,125,158,.13)"/><template #node-default="{data}"><div class="card" :class="'tone-'+data.tone"><Handle id="in" type="target" :position="Position.Left"/><Handle id="out" type="source" :position="Position.Right"/><strong>{{data.title}}</strong><small>{{data.sub}}</small></div></template></VueFlow></div></section></template>

<style scoped>
.workflow{overflow:hidden;border:1px solid #dfe6f0;border-radius:14px;background:#fff;margin:0 0 18px}.workflow>header{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:17px 20px;border-bottom:1px solid #edf1f6}.workflow h2{margin:0;font-size:16px}.workflow p{margin:5px 0 0;color:#7d8ca1;font-size:12px}.legend{display:flex;gap:12px;flex-wrap:wrap;color:#7d8ca1;font-size:10px}.legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.green{background:#16bb83}.yellow{background:#ffb21a}.blue{background:#1262df}.gray{background:#bdc8d6}.canvas{height:360px;background-color:#fbfcfe;background-image:radial-gradient(#e4eaf2 1.2px,transparent 1.2px);background-size:22px 22px}.canvas :deep(.vue-flow){background:transparent}.canvas :deep(.vue-flow__background){display:none}.canvas :deep(.vue-flow__edge-path){stroke:#d0d9e5;stroke-width:2}.canvas :deep(.vue-flow__node-default){border:0;background:none;padding:0;box-shadow:none}.card{box-sizing:border-box;width:232px;height:92px;display:grid;align-content:center;gap:8px;padding:12px 14px;border:1.5px solid #d9e2ee;border-radius:12px;background:white;box-shadow:0 2px 7px #1f314a0a;cursor:pointer}.card strong{font-size:12px;color:#263449;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card small{font-size:10px;color:#718198;line-height:1.45}.tone-success{border-color:#adebd5;background:#f2fbf7}.tone-warning{border:2px solid #ffb91e;background:#fffdf6}.tone-info{border:2px solid #1764df}.tone-muted{border-style:dashed;background:#fafbfd;opacity:.7}.card :deep(.vue-flow__handle){opacity:0}@media(max-width:700px){.workflow>header{align-items:flex-start;flex-direction:column}.canvas{height:330px}}
</style>
